sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

};

sp_widget.css:
.sobre-nos-widget {
   font-family: 'Roboto Flex', sans-serif;
   color: #293273;
   max-width: 800px;
   margin: 5rem auto;
   padding: 0 20px;
 }

 .sobre-nos-titulo {
   font-size: 0.9rem;
   font-weight: 600;
   color: #6CB4EE;
   text-transform: uppercase;
   margin-bottom: 0.5rem;
 }

 .sobre-nos-headline {
   font-size: 2rem;
   font-weight: 700;
   line-height: 1.3;
   color: #293273;
   margin-bottom: 1rem;
 }

 .sobre-nos-descricao {
   font-size: 1rem;
   color: #444;
   line-height: 1.6;
   margin-bottom: 3rem;
 }

 .sobre-nos-info-container {
   display: flex;
   flex-wrap: wrap;
   justify-content: space-between;
   gap: 1rem;
 }

 .sobre-nos-contato,
 .sobre-nos-redes {
   flex: 1;
   min-width: 250px;
 }

 .sobre-nos-contato h4,
 .sobre-nos-redes h4 {
   font-size: 0.9rem;
   color: #6CB4EE;
   font-weight: 600;
   margin-bottom: 0.5rem;
   text-transform: uppercase;
 }

 .sobre-nos-contato p,
 .sobre-nos-contato a {
   font-size: 0.95rem;
   color: #333;
   margin: 0.3rem 0;
   text-decoration: none;
 }

 .sobre-nos-redes .icon-container {
   display: flex;
   gap: 12px;
   align-items: center;
 }

 .sobre-nos-redes .icon-container a {
   font-size: 1.2rem;
   color: #293273;
   text-decoration: none;
 }

 /* Ícones simples com fontes como FontAwesome */
 .fa {
   font-family: "Font Awesome 5 Free"; 
   font-weight: 900;
 }

 /* Responsivo */
 @media (max-width: 600px) {
   .sobre-nos-info-container {
     flex-direction: column;
   }
 }
